import{_ as a,o as r,c as t,a2 as d}from"./chunks/framework.DTwTvi8b.js";const h=JSON.parse('{"title":"0010 需求总览现场生成，不维护 INDEX.md","description":"","frontmatter":{"editLink":false},"headers":[],"relativePath":"reference/adr/0010-generated-feature-overview.md","filePath":"reference/adr/0010-generated-feature-overview.md","lastUpdated":null}'),o={name:"reference/adr/0010-generated-feature-overview.md"};function i(n,e,s,c,l,u){return r(),t("div",null,[...e[0]||(e[0]=[d('<div><h1 id="_0010-需求总览现场生成-不维护-index-md" tabindex="-1">0010 需求总览现场生成，不维护 INDEX.md <a class="header-anchor" href="#_0010-需求总览现场生成-不维护-index-md" aria-label="Permalink to &quot;0010 需求总览现场生成，不维护 INDEX.md&quot;">​</a></h1><ul><li>状态：已采纳</li></ul><h2 id="背景" tabindex="-1">背景 <a class="header-anchor" href="#背景" aria-label="Permalink to &quot;背景&quot;">​</a></h2><p>设计方案计划在 <code>docs/features/INDEX.md</code> 中维护所有需求的一览。但每个需求在自己的 worktree 和分支上进行，如果每个分支都修改同一个提交进仓库的文件，合并时会反复冲突；而且一个工作区里看不到其他工作区尚未合并的需求。</p><h2 id="决定" tabindex="-1">决定 <a class="header-anchor" href="#决定" aria-label="Permalink to &quot;决定&quot;">​</a></h2><p>不提交 <code>INDEX.md</code>。<code>start-pipeline --list</code> 现场扫描这个仓库所有 worktree 中的 <code>docs/features/*/spec.md</code>、状态文件和验收记录，生成总览；同一需求出现在多个工作区时取最近更新的一份。<code>/req</code> 在路由、查看进度和接手时使用它。</p><h2 id="影响" tabindex="-1">影响 <a class="header-anchor" href="#影响" aria-label="Permalink to &quot;影响&quot;">​</a></h2><p>没有合并冲突，能看到所有工作区中的需求。代价是总览只在本机生成；不在这台机器上的工作区看不到。</p></div><p class="source-note">本页由仓库中的 <a href="https://github.com/yiyisf/paseo-req-kit/blob/main/docs/adr/0010-generated-feature-overview.md">docs/adr/0010-generated-feature-overview.md</a> 生成。<a href="https://github.com/yiyisf/paseo-req-kit/edit/main/docs/adr/0010-generated-feature-overview.md">在 GitHub 上编辑</a></p>',2)])])}const m=a(o,[["render",i]]);export{h as __pageData,m as default};
